// Validate Modbus read data before it is decoded or forwarded.
// Expected payload: uint16 register array, where each value is 0 to 65535.
// Invalid payloads are blocked by setting payload to 0 and msg.validPayload to false.

const input = msg.payload;
let validPayload = true;

// Confirm the payload is an array of valid Modbus register values.
if (!Array.isArray(input)) {
    validPayload = false;
} else if (!input.every((value) => Number.isInteger(value) && value >= 0 && value <= 65535)) {
    validPayload = false;
}

msg.validPayload = validPayload;

// Show validation result in the Node-RED editor.
if (!validPayload) {
    node.warn("Invalid Modbus read payload");
    node.status({ fill: "red", shape: "dot", text: "error" });
    msg.payload = 0;
} else {
    node.status({ fill: "green", shape: "dot", text: "OK" });
}

return msg;

// Purpose: Store the decoded PLC heartbeat value in Node-RED flow context.
// Input:   msg.payload.heartbeat (number) - decoded heartbeat value
// Output:  msg.payload { heartbeat, lastHeartbeatChange }
// Notes:   Heartbeat is an INT (0-9999) that increments each PLC scan and wraps back to 0.
//          Health is checked by "Check HeartBeat Health.js" from the saved flow context.

const currentHeartbeat = (Number(msg.payload.heartbeat) || 0) & 0xffff;
const now = Date.now();

const heartbeatStatus = flow.get("plcHeartbeat1Status") ?? {};
const previousHeartbeat = heartbeatStatus.heartbeat;

heartbeatStatus.heartbeat = currentHeartbeat;

if (currentHeartbeat !== previousHeartbeat) {
    heartbeatStatus.lastHeartbeatChange = now;
}

if (!heartbeatStatus.lastHeartbeatChange) {
    heartbeatStatus.lastHeartbeatChange = now;
}

flow.set("plcHeartbeat1Status", heartbeatStatus);

msg.payload = heartbeatStatus;
return msg;

