// Purpose: Check PLC heartbeat health from flow context on a periodic trigger.
// Input:   Any periodic msg, typically from an Inject node.
// Output:  msg.payload { isHealthy }
// Env:     PLC_DISCONNECT_TIMEOUT (ms) - max elapsed time without a heartbeat change before reporting unhealthy

const timeoutMs = Number(env.get("PLC_DISCONNECT_TIMEOUT")) || 5000;
const now = Date.now();

const plcHeartbeat1Status = flow.get("plcHeartbeat1Status") ?? {};
const plcHeartbeat2Status = flow.get("plcHeartbeat2Status") ?? {};
const plcHeartbeat3Status = flow.get("plcHeartbeat3Status") ?? {};

const heartbeat1Age = now - plcHeartbeat1Status.lastHeartbeatChange;
const heartbeat2Age = now - plcHeartbeat2Status.lastHeartbeatChange;
const heartbeat3Age = now - plcHeartbeat3Status.lastHeartbeatChange;

const isHealthy =
    heartbeat1Age <= timeoutMs &&
    heartbeat2Age <= timeoutMs &&
    heartbeat3Age <= timeoutMs;

node.status({
    fill: isHealthy ? "green" : "red",
    shape: isHealthy ? "dot" : "ring",
    text: isHealthy ? "healthy" : "disconnected",
});

msg.payload = { 
    isHealthy,
    lastUpdate: now,
    };
return msg;

// Purpose: Create PLC status payload for health reporting
