// Output:  msg.payload - status object containing timestamp, standpipe, and isHealthy

const inputPayload = msg.payload;

msg.payload = {
    lastUpdate: Date.now(),
    standpipe: inputPayload.standpipe,
    isHealthy: inputPayload.commsOK === true,
    type: "AWS PLC"
};

return msg;

