// Purpose: Build REST write payloads from decoded PLC AWS data and wsRead truck data.
// Input:   msg.payload (object) - decoded AWS data from "Decode Modbus Registers.js"
// Output:  message with msg.payload containing autonomousTruckName and truckLockReq

const awsPayload = msg.payload;
const wsRead = global.get("wsRead") ?? {};

const standpipe = awsPayload.standpipe;

if (!standpipe) {
    return null;
}

const truckName = wsRead[standpipe]?.TruckName;

if (!truckName) {
    return null;
}

msg.payload = {
    autonomousTruckName: truckName,
    truckLockReq: Boolean(awsPayload.truckLockReq),
};
msg.eventCode = awsPayload.eventCode;

return msg;

// Purpose: Build REST write payload for comms failure unlocking when the truck is motion locked.
// Input:   msg.payload (object) - decoded AWS data from "Decode Modbus Registers.js"
// Output:  message with msg.payload containing autonomousTruckName and truckLockReq

const awsPayload = msg.payload;
const wsRead = global.get("wsRead") ?? {};

const standpipe = awsPayload.standpipe;

if (!standpipe) {
    return null;
}

const truckName = wsRead[standpipe]?.TruckName;
const motionLocked = wsRead[standpipe]?.MotionLocked;

if (!truckName) {
    return null;
}

if (awsPayload.commsOK === false && motionLocked === true) {
    msg.payload = {
        autonomousTruckName: truckName,
        truckLockReq: false,
    };
    msg.standpipe = standpipe;

    return msg;
}


return null;

// Purpose: Build REST write payloads for FMS PLC heartbeat failure unlocking.
// Input:   msg.payload (object) - heartbeat status from "Check HeartBeat.js"
// Output:  messages with msg.payload containing autonomousTruckName and truckLockReq

const heartbeatPayload = msg.payload;
const wsRead = global.get("wsRead") ?? {};

if (heartbeatPayload.isHealthy !== false) {
    return null;
}

Object.keys(wsRead).forEach((standpipe) => {
    if (wsRead[standpipe]?.MotionLocked !== true) {
        return;
    }

    const truckName = wsRead[standpipe]?.TruckName;

    if (!truckName) {
        return;
    }

    node.send({
        ...msg,
        payload: {
            autonomousTruckName: truckName,
            truckLockReq: false,
        },
    });
});

return null;

