// Purpose: Block REST write messages unless commandType changes per truck
// Input:   msg.payload - REST write payload containing commandType and autonomousTruckName
// Output:  msg - original message when commandType changes for the truck

const inputPayload = msg.payload;
const blockUnlessValueChanges = inputPayload.commandType;
const applyModeSeparatelyForEach = inputPayload.autonomousTruckName;

