const previousValue = previousValueByGroup[applyModeSeparatelyForEach];

if (previousValue === blockUnlessValueChanges) {
    return null;
}

previousValueByGroup[applyModeSeparatelyForEach] = blockUnlessValueChanges;
flow.set("previousValueByGroup", previousValueByGroup);

return msg;

