const records = flow.get("awsUtilisationRecords") ?? {};
const record = records[standpipe];

if (!record) {
    return null;
}

if (record.Exit_Status === null) {
    record.Exit_Status = msg.exitStatus;
}

flow.set("awsUtilisationRecords", records);
return null;

// Purpose: Calculate fill volume for a completed utilisation record.
// Input:   msg.payload.standpipe

const standpipe = msg.payload?.standpipe;
const records = flow.get("awsUtilisationRecords") ?? {};
const record = records[standpipe];

if (!record) {
    return null;
}

const startLevel = record.Start_Level;
const endLevel = record.End_Level;

record.Fill_Volume =
    startLevel === null || endLevel === null
        ? 0
        : endLevel - startLevel;

flow.set("awsUtilisationRecords", records);
return msg;

